- (UILabel *)label:(NSString *)text size:(CGFloat)size color:(UIColor *)color weight:(UIFontWeight)weight { UILabel *l=[UILabel new]; l.text=text; l.font=[UIFont systemFontOfSize:size weight:weight]; l.textColor=color; l.numberOfLines=0; l.semanticContentAttribute=UISemanticContentAttributeForceRightToLeft; return l; }
- (NSString *)safeInfo:(NSString *)path { struct stat st; if(lstat(path.fileSystemRepresentation,&st)!=0) return @"غير موجود أو لا يمكن الوصول"; return [NSString stringWithFormat:@"موجود | الحجم %lld بايت | الصلاحيات %@",(long long)st.st_size,[NSString stringWithFormat:@"%04o",st.st_mode & 07777]]; }
- (NSString *)plist:(NSString *)path key:(NSString *)key { NSDictionary *d=[NSDictionary dictionaryWithContentsOfFile:path]; id v=d[key]; return v ? [v description] : @"غير متاح"; }
- (NSString *)runDPKG { NSString *exe=@"/var/jb/usr/bin/dpkg-query"; if(access(exe.fileSystemRepresentation,X_OK)!=0) return @"dpkg-query غير متاح في هذا الجهاز."; int fd[2]; if(pipe(fd)!=0)return @"تعذّر تشغيل dpkg-query."; posix_spawn_file_actions_t actions; posix_spawn_file_actions_init(&actions); posix_spawn_file_actions_adddup2(&actions,fd[1],STDOUT_FILENO); posix_spawn_file_actions_adddup2(&actions,fd[1],STDERR_FILENO); posix_spawn_file_actions_addclose(&actions,fd[0]); char *argv[]={(char *)exe.UTF8String,"-W","-f=${binary:Package}  ${Version}\\n",NULL}; pid_t pid=0; int rc=posix_spawn(&pid,exe.fileSystemRepresentation,&actions,NULL,argv,environ); posix_spawn_file_actions_destroy(&actions); close(fd[1]); if(rc){close(fd[0]);return @"تعذر تشغيل dpkg-query.";} NSMutableData *data=[NSMutableData data]; char buffer[4096]; ssize_t n; while((n=read(fd[0],buffer,sizeof(buffer)))>0 && data.length<65536)[data appendBytes:buffer length:(NSUInteger)n]; close(fd[0]); int status=0; waitpid(pid,&status,0); NSString *out=[[NSString alloc]initWithData:data encoding:NSUTF8StringEncoding] ?: @""; NSArray *rows=[out componentsSeparatedByCharactersInSet:NSCharacterSet.newlineCharacterSet]; NSMutableArray *clean=[NSMutableArray array]; for(NSString *r in rows) if(r.length && clean.count<100)[clean addObject:r]; return [NSString stringWithFormat:@"عدد الحزم المعروضة: %lu (حد أقصى 100)\n%@",(unsigned long)clean.count,clean.count?[clean componentsJoinedByString:@"\n"]:@"لا توجد بيانات متاحة"]; }
- (NSString *)createReport { NSMutableString *r=[NSMutableString string]; [r appendFormat:@"ZAIN AUDIT — تقرير فحص آمن\nتاريخ الإنشاء: %@\n%@\n",[NSDate date],[@"=" stringByPaddingToLength:50 withString:@"=" startingAtIndex:0]];
    [r appendString:@"\n[١] معلومات النظام\n"]; NSString *sp=@"/System/Library/CoreServices/SystemVersion.plist"; [r appendFormat:@"إصدار iOS: %@\nرقم البناء: %@\nاسم المنتج: %@\n",[self plist:sp key:@"ProductVersion"],[self plist:sp key:@"ProductBuildVersion"],[self plist:sp key:@"ProductName"]]; struct utsname u; if(uname(&u)==0)[r appendFormat:@"معمارية النظام: %s\n",u.machine];
    NSArray *paths=@[@"/",@"/var",@"/var/mobile",@"/var/jb",@"/var/jb/Applications",@"/var/jb/usr",@"/private/preboot",@"/var/containers/Bundle/Application",@"/var/mobile/Containers/Data/Application"]; [r appendString:@"\n[٢] نظام الملفات والمسارات\n"]; for(NSString *p in paths){[r appendFormat:@"%@ — %@",p,[self safeInfo:p]]; struct statvfs sv; if(statvfs(p.fileSystemRepresentation,&sv)==0)[r appendFormat:@" | المساحة المتاحة: %llu MB",(unsigned long long)(sv.f_bavail*sv.f_frsize/1048576)]; [r appendString:@"\n"];}
    [r appendString:@"\n[٣] مكونات الجيلبريك\n"]; for(NSString *p in @[@"/var/jb",@"/var/jb/basebin",@"/var/jb/usr/bin/dpkg",@"/var/jb/usr/bin/python3",@"/var/jb/Library",@"/var/jb/Applications"])[r appendFormat:@"%@ — %@\n",p,[self safeInfo:p]];
    [r appendString:@"\n[٤] حاويات التطبيقات (بيانات وصفية فقط)\n"]; for(NSString *root in @[@"/var/containers/Bundle/Application",@"/var/mobile/Containers/Data/Application"]){[r appendFormat:@"\nالمسار: %@\n",root]; NSError *e=nil; NSArray *items=[[NSFileManager defaultManager] contentsOfDirectoryAtPath:root error:&e]; NSUInteger count=0; for(NSString *item in items){if(count>=300)break; NSString *folder=[root stringByAppendingPathComponent:item]; BOOL dir=NO; if(![[NSFileManager defaultManager] fileExistsAtPath:folder isDirectory:&dir]||!dir)continue; count++; NSString *meta=[folder stringByAppendingPathComponent:@".com.apple.mobile_container_manager.metadata.plist"]; [r appendFormat:@"%@ | %@\n",item,[self plist:meta key:@"MCMMetadataIdentifier"]];} [r appendFormat:@"عدد الحاويات: %lu%@\n",(unsigned long)count,e?[NSString stringWithFormat:@" | %@",e.localizedDescription]:@""]; }
    [r appendString:@"\n[٥] بيانات وصفية لمسارات حساسة (لا تتم قراءة المحتوى)\n"]; for(NSString *p in @[@"/var/Keychains",@"/private/var/Keychains",@"/var/mobile/Library/Keychains",@"/var/mobile/Library/TCC/TCC.db",@"/var/mobile/Library/TCC",@"/var/mobile/Library/Preferences",@"/var/mobile/Library/Caches",@"/var/mobile/Library/Logs",@"/var/db"])[r appendFormat:@"%@ — %@\n",p,[self safeInfo:p]];
    [r appendString:@"\n[٦] الحزم المثبتة\n"]; [r appendFormat:@"%@\n",[self runDPKG]];
    [r appendString:@"\n[٧] ضمانات السلامة\nلم تُنفذ أي عملية حذف أو تعديل.\nلم تتم قراءة محتويات Keychain أو قواعد الخصوصية.\nاقتصر الفحص على معلومات النظام والبيانات الوصفية.\nانتهى التقرير.\n"]; return r; }
- (void)startScan { self.scanButton.enabled=NO; [self.scanButton setTitle:@"جارٍ الفحص…" forState:UIControlStateNormal]; self.statusLabel.text=@"يتم جمع البيانات الوصفية بأمان…"; dispatch_async(dispatch_get_global_queue(QOS_CLASS_USER_INITIATED,0),^{NSString *report=[self createReport]; NSString *docs=NSSearchPathForDirectoriesInDomains(NSDocumentDirectory,NSUserDomainMask,YES).firstObject; NSString *path=[docs stringByAppendingPathComponent:@"ZAIN_Audit_Report.txt"]; NSError *err=nil; BOOL ok=[report writeToFile:path atomically:YES encoding:NSUTF8StringEncoding error:&err]; dispatch_async(dispatch_get_main_queue(),^{self.report=report; self.reportView.text=report; self.reportView.textAlignment=NSTextAlignmentRight; self.statusLabel.text=ok?[NSString stringWithFormat:@"اكتمل الفحص • حُفظ التقرير داخل التطبيق\n%@",path]:[NSString stringWithFormat:@"اكتمل الفحص لكن تعذّر حفظ التقرير: %@",err.localizedDescription]; self.scanButton.enabled=YES; [self.scanButton setTitle:@"إعادة الفحص" forState:UIControlStateNormal];});}); }
- (void)shareReport { if(!self.report.length){UIAlertController *a=[UIAlertController alertControllerWithTitle:@"لا يوجد تقرير بعد" message:@"ابدأ الفحص أولاً لإنشاء تقرير." preferredStyle:UIAlertControllerStyleAlert]; [a addAction:[UIAlertAction actionWithTitle:@"حسنًا" style:UIAlertActionStyleDefault handler:nil]]; [self.window.rootViewController presentViewController:a animated:YES completion:nil]; return;} NSString *docs=NSSearchPathForDirectoriesInDomains(NSDocumentDirectory,NSUserDomainMask,YES).firstObject; NSString *path=[docs stringByAppendingPathComponent:@"ZAIN_Audit_Report.txt"]; [self.report writeToFile:path atomically:YES encoding:NSUTF8StringEncoding error:nil]; UIActivityViewController *share=[[UIActivityViewController alloc]initWithActivityItems:@[[NSURL fileURLWithPath:path]] applicationActivities:nil]; if(UIDevice.currentDevice.userInterfaceIdiom==UIUserInterfaceIdiomPad){share.popoverPresentationController.sourceView=self.reportView; share.popoverPresentationController.sourceRect=CGRectMake(self.reportView.bounds.size.width/2,0,1,1);} [self.window.rootViewController presentViewController:share animated:YES completion:nil]; }
